class TrieNode:
    def __init__(self):
        self.children = {}   # letter -> TrieNode
        self.top = []        # up to 3 smallest products that pass through here

def solution(products, search_word):
    root = TrieNode()
    for name in sorted(products):        # sorted, so the first 3 to arrive are the smallest
        node = root
        for ch in name:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            if len(node.top) < 3:
                node.top.append(name)
    out = []
    node = root
    for ch in search_word:
        if node is not None:
            node = node.children.get(ch)  # None once the prefix leaves the trie
        out.append(list(node.top) if node is not None else [])
    return out
